  ('AR_DOCUMENT_SETTLEMENT_DIFFERENCE', 'Saldo de la factura de venta distinto de lo cobrado',
   'Lo cobrado de la factura no es la suma de sus aplicaciones, retenciones y notas de crédito confirmadas. Error interno: repórtelo a soporte con la clave.'),
  ('APPLICATION_WITHOUT_P25_LINE', 'Aplicación de cobro sin su línea contable',
   'La aplicación no tiene exactamente una línea de cuentas por cobrar por su importe. Error interno: repórtelo a soporte con la clave.'),
  ('RECEIPT_GL_DIFFERENCE', 'Cobro distinto en la contabilidad',
   'El saldo del cobro en cobros sin aplicar o en efectivo en tránsito no coincide con el cobro. Error interno: repórtelo a soporte con la clave.'),
  ('FISCAL_DOCUMENT_PENDING', 'e-CF sin respuesta final',
   'Registre en la factura o nota de crédito la respuesta del proveedor de facturación electrónica.'),
  ('DELIVERY_OPEN', 'Conduce sin prueba de entrega',
   'Registre la prueba de entrega (POD), la devolución o la pérdida del conduce.'),
  ('WIP_GL_DIFFERENCE', 'Producción en proceso distinta de la contabilidad',
   'El saldo WIP del acumulador no es el consumo menos el estándar menos las variaciones liquidadas. Error interno: repórtelo a soporte con la clave.'),
  ('COLLECTOR_NOT_SETTLED', 'Acumulador de costos sin liquidar',
   'Liquide en Producción el acumulador de costos del mes terminado.'),
  ('RUN_NOT_POSTED', 'Corrida en proceso',
   'Contabilice el resumen de turno de la corrida, o anúlela si no se produjo.'),
  ('USAGE_OUT_OF_TOLERANCE', 'Consumo fuera de tolerancia',
   'Revise con el supervisor el pesaje y el consumo registrado; si la diferencia se repite, revise la receta.'),
  ('CURING_OVERDUE', 'Lote con curado vencido',
   'Libere el lote si está listo, o bloquéelo o descártelo si no cumple.'),
  ('CLOSE_ORDER', 'Componente cerrado fuera de orden',
   'Cierre primero el componente indicado en la clave: el día de operación (OP-DAY) antes que la liquidación de costos (COST-SET), y esta antes que el inventario (INV-MOV).'),
  ('AUTH_LINE_CONSUMPTION_DIFFERENCE', 'Consumo de la autorización distinto de sus movimientos',
   'Lo consumido de la línea de autorización no es la suma de sus consumos menos sus liberaciones. Error interno: repórtelo a soporte con la clave.'),
  ('INVOICE_CONSUMPTION_DIFFERENCE', 'Consumo de la línea de factura distinto de su neto',
