  ('IN_TRANSIT_AGED', 'Partida en tránsito antigua',
   'La partida lleva más de 30 días sin aparecer en el banco, o la línea del extracto sin contabilizarse. Aclárela con el banco y concíliela o corríjala.');
CREATE TRIGGER recon_classification_immutable BEFORE UPDATE OR DELETE ON rec.recon_classification FOR EACH ROW EXECUTE FUNCTION core.reject_mutation();
GRANT SELECT ON rec.recon_classification TO rochell_app;
